# Search for the task id
def search_files(path, task_id, max_depth=2):
    if max_depth <= 0:
        return []
    results = []
    for item in os.listdir(path):
        full_path = os.path.join(path, item)
        if os.path.isdir(full_path):
            results.extend(search_files(full_path, task_id, max_depth-1))
        elif task_id in item:
            results.append(full_path)
    if "programs" not in str(path):
        results.extend(search_files(os.path.join(path, "programs"), task_id, max_depth-1))
    return results

